#!/usr/bin/bash
#
# Efficiency experiments (RQ3, RQ4, RQ5).
#
#   1. build the python virtual environment (for plot.py)
#   2. run cmm_test over the artificial instances, appending to rq<N>_out.tsv
#   3. plot the results into plots/
#
# Instances are generated by ../data/run.sh and read from
# ../data/artificial_instances/. Run that first if they are not present.

set -euo pipefail

usage() {
    cat >&2 <<EOF
Usage: $0 -e <densities> -v <node counts> -x <taxid> -p <P> -r <trials> -k <K>
          -l <ells> -E <density> -L <ell> -d <D>
       $0 -P -L <ell>

Options:
  -e <list>  edge densities of the instances, in percent (e.g. "05 10"); RQ4 sweeps them
  -v <list>  node counts of the instances (e.g. "100 200"); RQ3 sweeps them
  -x <int>   taxid of the organism the instances were sampled from
  -p <int>   max number of threads; RQ3/RQ4 use it, RQ5 sweeps 1..P
  -r <int>   number of trials per configuration
  -k <int>   number K of top motif pairs kept by cmm_test
  -l <list>  motif lengths for RQ3/RQ4 (e.g. "5 8"); each runs with d = 0..ell-1
  -E <int>   edge density for RQ3 and RQ5 (one of -e)
  -L <int>   motif length for RQ5 (one of -l)
  -d <int>   number of wildcards for RQ5, in [0,ell)
  -P         only re-plot the existing TSVs (requires only -L)
  -h         show this help and exit
EOF
}

DENSITIES="" NODE_COUNTS="" INSTANCE_TAXID="" MAX_THREADS="" TRIALS="" K=""
ELLS="" FIXED_ED="" RQ5_ELL="" RQ5_D="" PLOT_ONLY=0

while getopts "e:v:x:p:r:k:l:E:L:d:Ph" opt
do
    case ${opt} in
        e) DENSITIES=${OPTARG} ;;
        v) NODE_COUNTS=${OPTARG} ;;
        x) INSTANCE_TAXID=${OPTARG} ;;
        p) MAX_THREADS=${OPTARG} ;;
        r) TRIALS=${OPTARG} ;;
        k) K=${OPTARG} ;;
        l) ELLS=${OPTARG} ;;
        E) FIXED_ED=${OPTARG} ;;
        L) RQ5_ELL=${OPTARG} ;;
        d) RQ5_D=${OPTARG} ;;
        P) PLOT_ONLY=1 ;;
        h) usage; exit 0 ;;
        *) usage; exit 1 ;;
    esac
done

declare -A FLAG=(
    [DENSITIES]=-e [NODE_COUNTS]=-v [INSTANCE_TAXID]=-x [MAX_THREADS]=-p
    [TRIALS]=-r [K]=-k [ELLS]=-l [FIXED_ED]=-E [RQ5_ELL]=-L [RQ5_D]=-d
)
if [ ${PLOT_ONLY} -eq 1 ]
then
    REQUIRED="RQ5_ELL"
    INTEGERS="RQ5_ELL"
    LISTS=""
else
    REQUIRED="DENSITIES NODE_COUNTS INSTANCE_TAXID MAX_THREADS TRIALS K ELLS FIXED_ED RQ5_ELL RQ5_D"
    INTEGERS="INSTANCE_TAXID MAX_THREADS TRIALS K FIXED_ED RQ5_ELL RQ5_D"
    LISTS="DENSITIES NODE_COUNTS ELLS"
fi
missing=""
for var in ${REQUIRED}
do
    [ -z "${!var}" ] && missing="${missing} ${FLAG[$var]}"
done
if [ -n "${missing}" ]
then
    echo "Error: missing required option(s):${missing}" >&2
    usage
    exit 1
fi
for var in ${INTEGERS}
do
    if ! [[ "${!var}" =~ ^[0-9]+$ ]]
    then
        echo "Error: ${FLAG[$var]} must be a non-negative integer, got '${!var}'." >&2
        exit 1
    fi
done
for var in ${LISTS}
do
    for value in ${!var}
    do
        if ! [[ "${value}" =~ ^[0-9]+$ ]]
        then
            echo "Error: ${FLAG[$var]} must be a list of non-negative integers, got '${!var}'." >&2
            exit 1
        fi
    done
done
if [ ${PLOT_ONLY} -eq 0 ]
then
    for var in MAX_THREADS TRIALS K
    do
        if [ "${!var}" -lt 1 ]
        then
            echo "Error: ${FLAG[$var]} must be >= 1, got '${!var}'." >&2
            exit 1
        fi
    done
    case " ${DENSITIES} " in
        *" ${FIXED_ED} "*) ;;
        *) echo "Error: -E ${FIXED_ED} is not one of the densities given with -e (${DENSITIES})." >&2; exit 1 ;;
    esac
    case " ${ELLS} " in
        *" ${RQ5_ELL} "*) ;;
        *) echo "Error: -L ${RQ5_ELL} is not one of the motif lengths given with -l (${ELLS})." >&2; exit 1 ;;
    esac
    if [ "${RQ5_D}" -ge "${RQ5_ELL}" ]
    then
        echo "Error: -d ${RQ5_D} must be smaller than -L ${RQ5_ELL}." >&2
        exit 1
    fi
fi

cd "$(dirname "$0")"

INSTANCE_DIR="../data/artificial_instances"
CMM_TEST="../bin/cmm_test"
PLOT="./plot.py"
VENV="venv"
PLOT_DIR="plots"

OUT_RQ3="rq3_out.tsv"
OUT_RQ4="rq4_out.tsv"
OUT_RQ5="rq5_out.tsv"

V_MAX=$(echo ${NODE_COUNTS} | tr ' ' '\n' | sort -n | tail -1)

# For a given ell, echo the wildcard counts d = 0 .. ell-1.
d_range() {
    seq 0 $(( $1 - 1 ))
}

# RQ5 thread counts: start at 1 and double up to MAX_THREADS.
rq5_thread_counts() {
    local threads=""
    local t=1
    while [ ${t} -lt ${MAX_THREADS} ]
    do
        threads="${threads} ${t}"
        t=$(( t * 2 ))
    done
    echo "${threads} ${MAX_THREADS}"
}

# Setup virtual environment
if [ ! -d "${VENV}" ]
then
    echo "Creating virtual environment..." >&2
    python3 -m venv ${VENV}
    ${VENV}/bin/pip install -q -r requirements.txt
fi
source ${VENV}/bin/activate

run_cmm_test() {
    local tsv=$1
    local trial=$2
    local fa=$3
    local int=$4
    local ell=$5
    local d=$6
    local threads=$7

    local key=$(basename ${fa} .fa)

    if [ ! -f "${fa}" ] || [ ! -f "${int}" ]
    then
        echo "Error: missing instance ${fa} / ${int}. Run ../data/run.sh first." >&2
        exit 1
    fi

    # TSV columns after prepended trial number:
    # 1:trial 2:instance 3:edge_density 4:V 5:N 6:ell 7:d
    # 8:max_rank 9:min_rank 10:avg_rank 11:pruning_cnt
    # 12:num_threads_requested 13:num_threads_spawned 14:time_ms 15:peak_ram_kb
    local uniq_pattern="${trial}|${key}|${ell}|${d}|${threads}"
    if [ -f "${tsv}" ] && (cut -f 1,2,6,7,12 ${tsv} | tr '\t' '|' | grep -qxF "${uniq_pattern}")
    then
        echo "Skipping trial=${trial} ${key} ell=${ell} d=${d} threads=${threads} -- already done" >&2
        return
    fi

    echo "Running trial=${trial} ${key} ell=${ell} d=${d} threads=${threads}" >&2
    ${CMM_TEST} ${fa} ${int} ${ell} ${d} ${K} ${threads} /dev/null \
        | awk -v trial=${trial} '{print trial "\t" $0}' >> ${tsv}
}

if [ ${PLOT_ONLY} -eq 0 ]
then
    ## Check that the binary and instances are present
    if [ ! -x "${CMM_TEST}" ]
    then
        echo "Error: ${CMM_TEST} not found or not executable. Run 'make' first." >&2
        exit 1
    fi
    if [ ! -d "${INSTANCE_DIR}" ]
    then
        echo "Error: ${INSTANCE_DIR} not found. Run ../data/run.sh first." >&2
        exit 1
    fi

    ## RQ3
    echo "Running experiment for RQ3..." >&2
    ED=${FIXED_ED}
    for trial in $(seq 1 ${TRIALS})
    do
        for v in ${NODE_COUNTS}
        do
            fa="${INSTANCE_DIR}/ed${ED}/sampled_${INSTANCE_TAXID}_V${v}_ed${ED}.fa"
            int="${INSTANCE_DIR}/ed${ED}/sampled_${INSTANCE_TAXID}_V${v}_ed${ED}.int"

            for ell in ${ELLS}
            do
                for d in $(d_range ${ell})
                do
                    run_cmm_test ${OUT_RQ3} ${trial} ${fa} ${int} ${ell} ${d} ${MAX_THREADS}
                done
            done
        done
    done

    ## RQ4
    echo "Running experiment for RQ4..." >&2
    V=${V_MAX}
    for trial in $(seq 1 ${TRIALS})
    do
        for ed in ${DENSITIES}
        do
            fa="${INSTANCE_DIR}/ed${ed}/sampled_${INSTANCE_TAXID}_V${V}_ed${ed}.fa"
            int="${INSTANCE_DIR}/ed${ed}/sampled_${INSTANCE_TAXID}_V${V}_ed${ed}.int"

            for ell in ${ELLS}
            do
                for d in $(d_range ${ell})
                do
                    run_cmm_test ${OUT_RQ4} ${trial} ${fa} ${int} ${ell} ${d} ${MAX_THREADS}
                done
            done
        done
    done

    ## RQ5
    echo "Running experiment for RQ5..." >&2
    ED=${FIXED_ED}
    V=${V_MAX}
    for trial in $(seq 1 ${TRIALS})
    do
        for t in $(rq5_thread_counts)
        do
            fa="${INSTANCE_DIR}/ed${ED}/sampled_${INSTANCE_TAXID}_V${V}_ed${ED}.fa"
            int="${INSTANCE_DIR}/ed${ED}/sampled_${INSTANCE_TAXID}_V${V}_ed${ED}.int"
            run_cmm_test ${OUT_RQ5} ${trial} ${fa} ${int} ${RQ5_ELL} ${RQ5_D} ${t}
        done
    done

    echo "Experiments for RQ3, RQ4, and RQ5 done." >&2
fi

## Plot
echo "Plotting results..." >&2
mkdir -p ${PLOT_DIR}

ANNOTATE="8:4 8:7 5:2 5:4"     # points annotated with max_rank
POLY_PAIRS="5:1 5:3 8:2 8:5"   # points given a polynomial fit on RQ3

# RQ3: log-scale both axes, quadratic fit on time, linear fit on memory per thread.
if [ ! -s "${OUT_RQ3}" ]
then
    echo "  ${OUT_RQ3} missing or empty, skipping rq3 plots" >&2
else
    echo "  rq3" >&2
    ${PLOT} \
        --input ${OUT_RQ3} \
        --rq rq3 \
        --output ${PLOT_DIR}/rq3 \
        --log-scale-time \
        --log-scale-mem \
        --fit-poly-time ${POLY_PAIRS} \
        --fit-poly-mem ${POLY_PAIRS} \
        --poly-degree-time 2 \
        --poly-degree-mem 1 \
        --no-poly-label \
        --max-rank ${ANNOTATE} \
        --mem-per-thread
fi

# RQ4: annotate selected points with max_rank (linear axes, no fits), memory per thread.
if [ ! -s "${OUT_RQ4}" ]
then
    echo "  ${OUT_RQ4} missing or empty, skipping rq4 plots" >&2
else
    echo "  rq4" >&2
    ${PLOT} \
        --input ${OUT_RQ4} \
        --rq rq4 \
        --output ${PLOT_DIR}/rq4 \
        --max-rank ${ANNOTATE} \
        --mem-per-thread
fi

# RQ5: speedup labels, log-scale both axes, total memory.
if [ ! -s "${OUT_RQ5}" ]
then
    echo "  ${OUT_RQ5} missing or empty, skipping rq5 plots" >&2
else
    echo "  rq5" >&2
    ${PLOT} \
        --input ${OUT_RQ5} \
        --rq rq5 \
        --output ${PLOT_DIR}/rq5 \
        --speedup \
        --rq5-ell ${RQ5_ELL} \
        --log-scale-time \
        --log-scale-mem
fi

echo "Done. Plots written to ${PLOT_DIR}/" >&2
